std::shared_ptr<EmojiCollection> CreatePetEmojiCollection(const std::string& species_id) {
    for (const auto& sp : kAllSpecies) {
        if (species_id == sp.id) {
            auto collection = std::make_shared<EmojiCollection>();
            for (unsigned int i = 0; i < sp.count; i++) {
                collection->AddEmoji(sp.assets[i].mood,
                    new LvglRawImage((void*)sp.assets[i].data, sp.assets[i].size));
            }
            return collection;
        }
    }
    return nullptr;  // especie sem GIFs ainda -- quem chamar mantem o padrao
}
